/**
 * Ambient HTTP request context for code running outside a controller's scope.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 *
 * A controller handler receives the request through `@Req()`. A service
 * function (`functions.ts`), a lifecycle hook and an entity method do not, yet
 * they run on a handler's call path and may read the request through the
 * `Request.*` DSL accessors and the caller through the `Auth.*` ones. This module binds the active request in an
 * `AsyncLocalStorage` for the whole async call path of each HTTP request, so
 * those accessors resolve anywhere on that path. A `Request.*` accessor fails
 * loud on any path that has no request (a job, a queue worker, startup), where
 * a request-scoped value has no meaning. The caller accessors (`currentUser*`)
 * answer an absent principal explicitly instead: the id is `null`, the role
 * check is `false`, and every other read raises -- never a fabricated value.
 *
 * `requestContextMiddleware` is installed by `main.ts`, and by every serverless
 * container HTTP app, before any other middleware, guard, or handler runs; the guards that later attach the
 * verified principal to `request.user` mutate the same object this store holds.
 * A serverless invocation that reaches no Express app (a Lambda or Azure
 * Functions adapter) binds its own `BoundRequest` the same way through
 * `runWithBoundRequest`, so every accessor answers identically on every hosting
 * path. Each binding carries the caller-address resolver of its path: the
 * listener's policy under the middleware, the serverless host's policy under an
 * adapter.
 */
import { AsyncLocalStorage } from 'node:async_hooks';
import type { IncomingHttpHeaders } from 'node:http';
import { UnauthorizedException } from '@nestjs/common';
import type { NextFunction, Request, Response } from 'express';
import { clientAddress } from '../common/client-address';
import { MissingTenantException } from '../errors/business-error';
import { bearerTokenOrForbidden } from '../auth/auth-chain';
import { PROBLEM_TYPES } from '../errors/problem-details.dto';
import type { IdentityPrincipal } from '../auth/identity';

/**
 * What every `Request.*` and `Auth.*` accessor reads from the active request. An
 * Express request is one; a serverless adapter builds one from its invocation.
 * The tenant binding (`TenantGuard`, or `AuthGuard` for a jwt tenant) writes
 * `tenantId` once it resolved and validated it.
 */
export interface BoundRequest {
  /** Every header, keyed by lower-case name; cookies are read from `headers.cookie`. */
  readonly headers: IncomingHttpHeaders;
  /** The verified principal the auth chain attached. */
  user?: IdentityPrincipal;
  tenantId?: string;
}

/** Resolves the caller's canonical address of the active request, `null` when it has none. */
export type ClientAddressResolver = () => string | null;

interface Binding {
  readonly request: BoundRequest;
  /** `null` where the service serves no HTTP request surface its platform names a caller address for. */
  readonly clientAddress: ClientAddressResolver | null;
}

const _requestStore = new AsyncLocalStorage<Binding>();

/** Express middleware binding the active request for its whole async call path. */
export function requestContextMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction,
): void {
  _requestStore.run({ request: req, clientAddress: () => clientAddress(req) }, next);
}

/**
 * Run `body` with `request` bound as the active request for its whole async call
 * path -- how a serverless adapter that reaches no Express app binds its invocation.
 */
export function runWithBoundRequest<T>(
  request: BoundRequest,
  clientAddress: ClientAddressResolver,
  body: () => Promise<T>,
): Promise<T> {
  return _requestStore.run({ request, clientAddress }, body);
}

/**
 * The `Cookie` header as `name -> value`, a repeated name keeping its last value.
 * Every `Request` cookie read parses the header here: Express fills `req.cookies`
 * only under a cookie-parsing middleware, which this service does not install.
 */
export function parseCookieHeader(header: string | undefined): Record<string, string> {
  const cookies: Record<string, string> = {};
  for (const chunk of (header ?? '').split(';')) {
    const separator = chunk.indexOf('=');
    const name = (separator < 0 ? '' : chunk.slice(0, separator)).trim();
    const raw = (separator < 0 ? chunk : chunk.slice(separator + 1)).trim();
    if (name !== '') {
      cookies[name] = raw.length >= 2 && raw.startsWith('"') && raw.endsWith('"') ? raw.slice(1, -1) : raw;
    }
  }
  return cookies;
}

/**
 * The `BoundRequest` of one serverless invocation, from the headers its host handed
 * over in any casing: names lower-cased (a name sent in two casings joined with
 * `, `, as Node joins a repeated header).
 */
export function invocationRequest(headers: Readonly<Record<string, string | undefined>>): BoundRequest {
  const lowered: Record<string, string> = {};
  for (const [name, value] of Object.entries(headers)) {
    if (value === undefined) {
      continue;
    }
    const key = name.toLowerCase();
    lowered[key] = key in lowered ? `${lowered[key]}, ${value}` : value;
  }
  return { headers: lowered };
}

/**
 * The HTTP request being served on this call path, or `undefined` when none is
 * active (a job, a queue worker, startup). Non-throwing: for the accessors
 * whose contract is "absent outside a request".
 */
function activeRequest(): BoundRequest | undefined {
  return _requestStore.getStore()?.request;
}

function activeBinding(): Binding {
  const binding = _requestStore.getStore();
  if (binding === undefined) {
    throw new Error(
      'No active HTTP request: a Request.* accessor was evaluated outside an HTTP ' +
        'request (a job, a queue worker, or startup). Request context exists only on ' +
        'the call path of a controller handler; pass the value in as a parameter ' +
        'when the function must also run elsewhere.',
    );
  }
  return binding;
}

/**
 * The HTTP request being served on this call path.
 *
 * @throws Error when no HTTP request is active -- the caller is a job, a queue
 *   worker, or startup code, where request context does not exist.
 */
export function currentRequest(): BoundRequest {
  return activeBinding().request;
}

/**
 * The cookies of the HTTP request being served on this call path, by cookie name.
 *
 * @throws Error when no HTTP request is active, as `currentRequest`.
 */
export function currentRequestCookies(): Record<string, string> {
  return parseCookieHeader(currentRequest().headers.cookie);
}


/** The verified principal `AuthGuard` attached to the active request, or `undefined`. */
function activePrincipal(): IdentityPrincipal | undefined {
  return activeRequest()?.user;
}

/**
 * The principal an `Auth.<member>` read requires.
 *
 * @throws Error when no HTTP request is active (a lifecycle hook, service function or
 *   entity method run by a job, a queue worker or startup), naming the member.
 * @throws UnauthorizedException when a request is active but anonymous (an optional
 *   route served without a credential) -- the opaque 401 problem `AuthGuard` throws.
 */
function requirePrincipal(member: string): IdentityPrincipal {
  const request = activeRequest();
  if (request === undefined) {
    throw new Error(
      `Auth.${member} was read outside an authenticated HTTP request (a lifecycle hook, ` +
        'service function or entity method run by a job, a queue worker or startup). Pass ' +
        'the value in as a parameter when the code must also run there.',
    );
  }
  const principal = request.user;
  if (principal === undefined) {
    // Opaque: the registered family's title, never a reason.
    throw new UnauthorizedException(PROBLEM_TYPES["unauthorized"].title);
  }
  return principal;
}

/**
 * Resolved local id of the authenticated principal (never the raw provider
 * `sub`), typed via the global `Express.Request` augmentation in identity.ts --
 * no `any` cast. `null` on an anonymous request and outside a request.
 */
export function currentUserId(): string | null {
  return activePrincipal()?.userId ?? null;
}

/** The principal with `id` aliased to its resolved `userId` (what `Auth.user()` reads). */
export function currentUser(): IdentityPrincipal & { readonly id: string } {
  const principal = requirePrincipal('user');
  return { ...principal, id: principal.userId };
}

/**
 * The bearer token the principal was authenticated with (the `Auth` token read).
 *
 * @throws ForbiddenException when the principal carries no forwardable credential
 *   (an API-key principal): the raw key is never forwarded downstream.
 */
export function currentUserToken(): string {
  return bearerTokenOrForbidden(requirePrincipal('token'));
}

/** The raw provider subject of the principal (what `Auth.subject` reads). */
export function currentUserSubject(): IdentityPrincipal['subject'] {
  return requirePrincipal('subject').subject;
}

/** The projected local profile of the principal (what `Auth.profile` reads). */
export function currentUserProfile(): IdentityPrincipal['profile'] {
  return requirePrincipal('profile').profile;
}

/** The identity of the principal (what `Auth.identity.<field>` reads): declared fields read through their claim paths. */
export function currentUserIdentity(): IdentityPrincipal['identity'] {
  return requirePrincipal('identity').identity;
}

/** `false` without a principal: no principal grants nothing. */
export function currentUserHasRole(role: string): boolean {
  return activePrincipal()?.roles.includes(role) ?? false;
}

/**
 * Tenant of the request being served: the value the tenant binding (`TenantGuard`,
 * or `AuthGuard` for a jwt tenant) resolved from the configured tenant source and
 * validated -- never a client-writable principal claim read around the binding.
 *
 * Fails closed: every query over a tenant-scoped entity is filtered by this
 * value, so a request that reached a handler with no tenant bound (relaxed
 * enforcement, a missing identifier) is rejected here rather than querying
 * with an absent tenant.
 *
 * @throws MissingTenantException when the request carries no resolved tenant.
 */
export function currentTenantId(): string {
  const tenantId = currentRequest().tenantId;
  if (tenantId === undefined || tenantId === '') {
    throw new MissingTenantException();
  }
  return tenantId;
}

/**
 * Whether the request being served has a resolved tenant -- `false` exactly where
 * `currentTenantId()` would refuse. Never refuses, reads no row and returns no tenant,
 * so a route can answer a caller with no tenant itself.
 */
export function currentHasTenant(): boolean {
  const tenantId = currentRequest().tenantId;
  return tenantId !== undefined && tenantId !== '';
}

/**
 * Caller address of the active request under its hosting path's platform policy,
 * resolved by the binding's resolver -- never read from a header here; empty when the
 * request has no caller address.
 *
 * @throws Error outside a request, and on a request of a service that serves no HTTP
 *   request surface its platform names a caller address for.
 */
export function currentClientIp(): string {
  const binding = activeBinding();
  if (binding.clientAddress === null) {
    throw new Error(
      'Request.ip() was evaluated in a service that declares no HTTP request surface (no ' +
        'rest_api, graphql_api, websocket_api or serverless endpoint behind an exposed ' +
        'ingress), so its platform names no caller address for it. Declare an HTTP surface ' +
        'on the service, or stop reading the caller address here.',
    );
  }
  return binding.clientAddress() ?? '';
}
